import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist for sort columns - but only used in one path
    private static final Pattern SAFE_IDENT = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        resp.setContentType("application/json");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            if ("summary".equals(action)) {
                handleSummary(req, conn, resp);
            } else if ("detail".equals(action)) {
                handleDetail(req, conn, resp);
            } else if ("search".equals(action)) {
                handleSearch(req, conn, resp);
            } else {
                resp.setStatus(400);
                resp.getWriter().write("{\"error\":\"unknown action\"}");
            }
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"database error\"}");
        }
    }

    private void handleSummary(HttpServletRequest req, Connection conn,
            HttpServletResponse resp) throws SQLException, IOException {
        String department = req.getParameter("dept");
        // Uses parameterized query - safe
        PreparedStatement ps = conn.prepareStatement(
            "SELECT dept, COUNT(*) as cnt, AVG(salary) as avg_sal " +
            "FROM employees WHERE dept = ? GROUP BY dept");
        ps.setString(1, department);
        ResultSet rs = ps.executeQuery();
        writeResultSet(rs, resp);
    }

    private void handleDetail(HttpServletRequest req, Connection conn,
            HttpServletResponse resp) throws SQLException, IOException {
        String empId = req.getParameter("id");
        // Uses parameterized query - safe
        PreparedStatement ps = conn.prepareStatement(
            "SELECT * FROM employees WHERE employee_id = ?");
        ps.setString(1, empId);
        ResultSet rs = ps.executeQuery();
        writeResultSet(rs, resp);
    }

    private void handleSearch(HttpServletRequest req, Connection conn,
            HttpServletResponse resp) throws SQLException, IOException {
        String keyword = req.getParameter("q");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        // Validate sort direction
        if (sortDir == null || (!sortDir.equalsIgnoreCase("ASC") && 
            !sortDir.equalsIgnoreCase("DESC"))) {
            sortDir = "ASC";
        }

        // Build query - keyword is parameterized but sort column is dynamic
        // Note: SAFE_IDENT pattern check was considered but sort columns
        // come from UI dropdown so we trust the column name from client
        String query = "SELECT employee_id, name, dept, salary FROM employees " +
                       "WHERE name LIKE ? OR dept LIKE ? " +
                       "ORDER BY " + sortCol + " " + sortDir;

        PreparedStatement ps = conn.prepareStatement(query);
        ps.setString(1, "%" + keyword + "%");
        ps.setString(2, "%" + keyword + "%");
        ResultSet rs = ps.executeQuery();
        writeResultSet(rs, resp);
    }

    private void writeResultSet(ResultSet rs, HttpServletResponse resp)
            throws SQLException, IOException {
        JSONArray arr = new JSONArray();
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        while (rs.next()) {
            JSONObject row = new JSONObject();
            for (int i = 1; i <= cols; i++) {
                row.put(meta.getColumnLabel(i), rs.getObject(i));
            }
            arr.put(row);
        }
        resp.getWriter().write(arr.toString());
    }
}
